98	+
99	+@MiscApi
100	+@RequiredArgsConstructor
101	+public class ColoringBookController {
102	+
103	+    private final CustomPDFDocumentFactory pdfDocumentFactory;
104	+
105	+    @AutoJobPostMapping(
106	+            consumes = MediaType.MULTIPART_FORM_DATA_VALUE,
107	+            value = "/coloring-book",
108	+            resourceWeight = ResourceWeight.LARGE_WEIGHT)
109	+    @StandardPdfResponse
110	+    @ToolIO(
111	+            accepts = ToolFormat.IMAGE,
112	+            imageIOInput = true,
113	+            produces = ToolFormat.PDF,
114	+            arity = ToolArity.MISO)
115	+    @Operation(
116	+            summary = "Create a coloring book from images",
117	+            description =
118	+                    "Places each image on its own A4 page, in order, and follows every image"
119	+                            + " page with a blank page so the back of each image is empty when"
120	+                            + " printed double-sided.")
121	+    public ResponseEntity<byte[]> createColoringBook(@ModelAttribute ColoringBookRequest request)
122	+            throws IOException {
123	+        MultipartFile[] images = request.getFileInput();
124	+        if (images == null || images.length == 0) {
125	+            throw ExceptionUtils.createIllegalArgumentException(
126	+                    "error.coloringBookImagesRequired", "At least one image is required");
127	+        }
128	+        byte[] pdf = PdfUtils.imagesToColoringBook(images, pdfDocumentFactory);
129	+        return WebResponseUtils.bytesToWebResponse(
130	+                pdf,
131	+                GeneralUtils.generateFilename(
132	+                        images[0].getOriginalFilename(), "_coloring_book.pdf"));
133	+    }
134	+}
